#[derive(Clone)]
struct Node{w:u64,id:usize,children:Vec<Node>}
fn tree(f:&[u32;256])->Option<Node>{let mut q:Vec<_>=f.iter().enumerate().filter(|(_,w)|**w>0).map(|(id,&w)|Node{w:w as u64,id,children:vec![]}).collect();if q.is_empty(){return None}if q.len()%2==0{q.push(Node{w:0,id:256,children:vec![]})}let mut id=257;while q.len()>1{q.sort_by_key(|n|(n.w,n.id));let children:Vec<_>=q.drain(..3).collect();q.push(Node{w:children.iter().map(|n|n.w).sum(),id,children});id+=1}q.pop()}
fn walk(n:&Node,p:&mut Vec<u8>,codes:&mut [Vec<u8>]){if n.children.is_empty(){if n.id<256{codes[n.id]=p.clone()}}else{for(i,c)in n.children.iter().enumerate(){p.push(i as u8);walk(c,p,codes);p.pop();}}}
pub fn encode(b:&[u8])->Vec<u8>{let mut f=[0u32;256];for &x in b{f[x as usize]+=1}let mut out=Vec::new();for x in f{out.extend_from_slice(&x.to_be_bytes())}let mut codes=vec![vec![];256];if let Some(root)=tree(&f){walk(&root,&mut vec![],&mut codes)}let(mut v,mut k)=(0u8,0u32);for &x in b{for &t in &codes[x as usize]{v=v*3+t;k+=1;if k==5{out.push(v);v=0;k=0}}}if k>0{out.push(v*3u8.pow(5-k))}out}
pub fn decode(b:&[u8],limit:usize)->Result<Vec<u8>,&'static str>{if b.len()<1024{return Err("huffman header")}let mut f=[0u32;256];for(i,c)in b[..1024].chunks_exact(4).enumerate(){f[i]=u32::from_be_bytes(c.try_into().unwrap())}let n:u64=f.iter().map(|&x|x as u64).sum();if n>limit as u64{return Err("limit")}let n=n as usize;let Some(root)=tree(&f)else{return Ok(vec![])};if root.children.is_empty(){return Ok(vec![root.id as u8;n])}let mut node=&root;let mut out=Vec::with_capacity(n);for &v in &b[1024..]{if v>=243{return Err("trit pack")}for k in (0..5).rev(){node=&node.children[(v/3u8.pow(k)%3) as usize];if node.children.is_empty(){if node.id>255{return Err("dummy")}out.push(node.id as u8);node=&root;if out.len()==n{return Ok(out)}}}}Err("truncated huffman")}
